Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -32,4 +32,104 @@
   </section>
   <footer class="bottomline"><span class="desktop-hint"><strong>MOVE</strong> <span class="key">W</span><span class="key">A</span><span class="key">S</span><span class="key">D</span> or arrows &nbsp; <strong>DASH</strong> <span class="key">SPACE</span></span><span class="mobile-hint">Use the pad to move · Tap to dash</span><span>Made with <strong>extra cheese</strong> 🧀</span></footer>
 </main>
 <script>
+(() => {
+  const canvas = document.getElementById('game');
+  const ctx = canvas.getContext('2d');
+  const stage = document.getElementById('stage');
+  const overlay = document.getElementById('overlay');
+  const startBtn = document.getElementById('startBtn');
+  const W = 960, H = 600, TILE = 48, MAP_X = 0, MAP_Y = 12;
+  const mapRows = [
+    '####################',
+    '#....#.......#.....#',
+    '#.##.#.#####.#.###.#',
+    '#.#..#...#...#...#.#',
+    '#.#.###..#..###..#.#',
+    '#...#....#.....#...#',
+    '###.#.######.#.###.#',
+    '#...#....#...#.....#',
+    '#.######.#.#####.#.#',
+    '#........#.......#.#',
+    '#.#########.#####..#',
+    '####################'
+  ];
+  const walls = mapRows.map(row => [...row].map(c => c === '#'));
+  const scoreEl = document.getElementById('score');
+  const livesEl = document.getElementById('lives');
+  const countEl = document.getElementById('sliceCount');
+  const progressEl = document.getElementById('progress');
+  const timerEl = document.getElementById('timer');
+  const headline = document.getElementById('headline');
+  const message = document.getElementById('message');
+  const soundBtn = document.getElementById('soundBtn');
+  let dpr = 1, running = false, won = false, last = 0, elapsed = 0, timeLeft = 60;
+  let score = 0, lives = 3, collected = 0, slices = [], particles = [];
+  let audioOn = false, audioCtx = null, shake = 0, flash = 0;
+  const keys = new Set(), touchDirs = new Set();
+  const player = {x: 1.5*TILE, y: 1.5*TILE, r: 13, speed: 175, dx: 1, dy: 0, dash: 0, dashCd: 0, invuln: 0};
+  const pizza = {x: 18.5*TILE, y: 10.5*TILE, r: 18, speed: 64, angle: 0};
+  const rand = (a,b) => a + Math.random()*(b-a);
+  function resize(){
+    const rect = stage.getBoundingClientRect();
+    dpr = Math.min(window.devicePixelRatio || 1, 2);
+    canvas.width = Math.round(rect.width*dpr); canvas.height = Math.round(rect.height*dpr);
+    ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0);
+  }
+  window.addEventListener('resize', resize); resize();
+  function wallAt(px,py){
+    const c=Math.floor((px-MAP_X)/TILE), r=Math.floor((py-MAP_Y)/TILE);
+    return r<0 || c<0 || r>=walls.length || c>=walls[0].length || walls[r][c];
+  }
+  function hitsWall(x,y,r){
+    return wallAt(x-r,y-r)||wallAt(x+r,y-r)||wallAt(x-r,y+r)||wallAt(x+r,y+r)||wallAt(x,y-r)||wallAt(x,y+r)||wallAt(x-r,y)||wallAt(x+r,y);
+  }
+  function movePlayer(dx,dy,dt){
+    const speed = player.speed * (player.dash>0 ? 2.45 : 1);
+    const nx=player.x+dx*speed*dt, ny=player.y+dy*speed*dt;
+    if(!hitsWall(nx,player.y,player.r)) player.x=nx;
+    if(!hitsWall(player.x,ny,player.r)) player.y=ny;
+  }
+  function spawnSlices(){
+    slices=[];
+    let tries=0;
+    while(slices.length<8&&tries++<1000){
+      const c=1+Math.floor(Math.random()*18), r=1+Math.floor(Math.random()*9);
+      if(walls[r][c]) continue;
+      const x=(c+.5)*TILE, y=MAP_Y+(r+.5)*TILE;
+      if(Math.hypot(x-player.x,y-player.y)<100||Math.hypot(x-pizza.x,y-pizza.y)<80) continue;
+      if(slices.some(s=>Math.hypot(s.x-x,s.y-y)<50)) continue;
+      slices.push({x,y,phase:rand(0,6.28),got:false});
+    }
+  }
+  function reset(){
+    score=0;lives=3;collected=0;elapsed=0;timeLeft=60;won=false;shake=0;flash=0;particles=[];
+    Object.assign(player,{x:1.5*TILE,y:1.5*TILE,dx:1,dy:0,dash:0,dashCd:0,invuln:1.3});
+    Object.assign(pizza,{x:18.5*TILE,y:10.5*TILE,speed:64,angle:0});
+    spawnSlices(); updateHud();
+  }
+  function updateHud(){
+    scoreEl.textContent=String(score).padStart(4,'0');
+    livesEl.textContent=Array.from({length:3},(_,i)=>i<lives?'♥':'♡').join(' ');
+    countEl.textContent=collected;progressEl.style.width=(collected/8*100)+'%';timerEl.textContent=Math.max(0,Math.ceil(timeLeft));
+  }
+  function begin(){reset();running=true;overlay.classList.add('hidden');last=performance.now();if(audioOn) initSound();}
+  startBtn.addEventListener('click',begin);
+  const keyMap={ArrowUp:'up',KeyW:'up',ArrowDown:'down',KeyS:'down',ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right'};
+  window.addEventListener('keydown',e=>{
+    if(keyMap[e.code]){keys.add(keyMap[e.code]);e.preventDefault();}
+    if(e.code==='Space'){e.preventDefault();if(!e.repeat) dash();}
+    if((e.code==='Enter'||e.code==='Space')&&!running) begin();
+  });
+  window.addEventListener('keyup',e=>{if(keyMap[e.code])keys.delete(keyMap[e.code]);});
+  function dash(){if(!running||player.dashCd>0)return;player.dash=.19;player.dashCd=1.15;player.invuln=Math.max(player.invuln,.23);sound(430,.08);}
+  document.querySelectorAll('.touch-pad button').forEach(btn=>{
+    const dir=btn.dataset.dir;
+    btn.addEventListener('pointerdown',e=>{e.preventDefault();btn.setPointerCapture(e.pointerId);touchDirs.add(dir);});
+    const release=e=>{e.preventDefault();touchDirs.delete(dir);};
+    btn.addEventListener('pointerup',release);btn.addEventListener('pointercancel',release);btn.addEventListener('lostpointercapture',()=>touchDirs.delete(dir));
+  });
+  stage.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'&&running&&e.target===canvas)dash();});
+  soundBtn.addEventListener('click',()=>{audioOn=!audioOn;soundBtn.textContent=audioOn?'♫':'♪';soundBtn.style.color=audioOn?'#ffca66':'';if(audioOn)initSound();});
+  function initSound(){if(!audioCtx)audioCtx=new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();}
+  function sound(freq=520,duration=.09){if(!audioOn)return;initSound();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.055,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration);}

input.newString:
function sound(freq=520,duration=.09){if(!audioOn)return;initSound();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.055,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration);}
function burst(x,y,color,n=10){for(let i=0;i<n;i++){const a=rand(0,Math.PI*2),v=rand(35,145);particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:rand(.35,.8),max:.8,color,size:rand(2,5)});}}
function finish(victory){
  running=false;won=victory;overlay.classList.remove('hidden');
  if(victory){headline.innerHTML='Slice of<br><span>victory!</span>';message.textContent='You scooped up every topping and left that clingy crust in the dust. The kitchen is yours!';startBtn.textContent='Play again';sound(760,.25);}
  else{headline.innerHTML='You got<br><span>served!</span>';message.textContent=lives<=0?'That crust caught up with you. The toppings are still out there — give it another go!':'Time ran out! The pizza is still hungry. Try again and keep moving!';startBtn.textContent='Try again';sound(150,.3);}
}
function update(dt){
  elapsed+=dt;timeLeft-=dt;player.invuln=Math.max(0,player.invuln-dt);player.dash=Math.max(0,player.dash-dt);player.dashCd=Math.max(0,player.dashCd-dt);shake=Math.max(0,shake-dt*20);flash=Math.max(0,flash-dt*2);
  if(timeLeft<=0){timeLeft=0;updateHud();finish(false);return;}
  let dx=(keys.has('right')||touchDirs.has('right')?1:0)-(keys.has('left')||touchDirs.has('left')?1:0);
  let dy=(keys.has('down')||touchDirs.has('down')?1:0)-(keys.has('up')||touchDirs.has('up')?1:0);
  const len=Math.hypot(dx,dy);if(len){dx/=len;dy/=len;player.dx=dx;player.dy=dy;movePlayer(dx,dy,dt);}
  pizza.speed=64+collected*3.1+Math.min(elapsed*.28,12);
  const toX=player.x-pizza.x,toY=player.y-pizza.y,dist=Math.hypot(toX,toY)||1;
  pizza.x+=toX/dist*pizza.speed*dt;pizza.y+=toY/dist*pizza.speed*dt;pizza.angle+=dt*(2.5+collected*.1);
  for(const s of slices){if(!s.got&&Math.hypot(player.x-s.x,player.y-s.y)<player.r+13){s.got=true;collected++;score+=100;burst(s.x,s.y,'#ffcb64',12);sound(620+collected*38,.11);flash=.15;}}
  if(collected>=8){score+=Math.ceil(timeLeft)*10;updateHud();finish(true);return;}
  if(player.invuln<=0&&Math.hypot(player.x-pizza.x,player.y-pizza.y)<player.r+pizza.r-3){
    lives--;player.invuln=1.8;shake=9;flash=.4;score=Math.max(0,score-50);burst(player.x,player.y,'#ff715d',18);sound(180,.2);
    if(lives<=0){updateHud();finish(false);return;}
    // A quick respawn buys a moment, but the relentless slice keeps coming.
    player.x=1.5*TILE;player.y=1.5*TILE;
  }
  for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.1,dt);p.vy*=Math.pow(.1,dt);p.life-=dt;}
  particles=particles.filter(p=>p.life>0);updateHud();
}
function roundedRect(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);}
function drawBackground(){
  ctx.fillStyle='#242329';ctx.fillRect(0,0,W,H);
  // subtle checkerboard floor and warm pools of light
  for(let r=0;r<12;r++)for(let c=0;c<20;c++){
    const x=c*TILE,y=MAP_Y+r*TILE;
    if(!walls[r][c]){ctx.fillStyle=(r+c)%2?'#29282e':'#2b2a30';ctx.fillRect(x,y,TILE,TILE);ctx.fillStyle='#ffffff04';ctx.fillRect(x+5,y+5,1,1);}
  }
  const glow=ctx.createRadialGradient(player.x,player.y,20,player.x,player.y,300);glow.addColorStop(0,'#ffca660c');glow.addColorStop(1,'#ffca6600');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H);
}
function drawWalls(){
  for(let r=0;r<12;r++)for(let c=0;c<20;c++)if(walls[r][c]){
    const x=c*TILE,y=MAP_Y+r*TILE;
    ctx.fillStyle='#14141a';ctx.fillRect(x,y,TILE,TILE);
    ctx.fillStyle='#34323a';roundedRect(x+2,y+2,TILE-4,TILE-4,8);ctx.fill();
    ctx.fillStyle='#403d45';roundedRect(x+5,y+5,TILE-10,5,3);ctx.fill();
    ctx.fillStyle='#27262d';ctx.fillRect(x+5,y+13,TILE-10,TILE-18);
    // tiny tile seams create a hand-laid kitchen-brick feel
    ctx.fillStyle='#ffffff08';ctx.fillRect(x+8,y+22,TILE-16,1);
    ctx.strokeStyle='#514a4d';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x+7,y+TILE-4);ctx.lineTo(x+TILE-7,y+TILE-4);ctx.stroke();
  }
  // little route markers in the floor
  ctx.save();ctx.globalAlpha=.22;ctx.fillStyle='#ffcb6b';
  [[1.5,1.5],[18.5,10.5]].forEach(([c,r])=>{ctx.beginPath();ctx.arc(c*TILE,MAP_Y+r*TILE,3,0,Math.PI*2);ctx.fill();});ctx.restore();
}
function drawSlice(s){
  const bob=Math.sin(elapsed*4+s.phase)*3, x=s.x,y=s.y+bob;
  ctx.save();ctx.translate(x,y);ctx.rotate(.1*Math.sin(elapsed*2+s.phase));
  ctx.shadowColor='#ffca66';ctx.shadowBlur=16;ctx.fillStyle='#ffd978';
  ctx.beginPath();ctx.moveTo(-11,-9);ctx.lineTo(12,-5);ctx.lineTo(3,12);ctx.closePath();ctx.fill();ctx.shadowBlur=0;
  ctx.strokeStyle='#fff0ad';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#f58a45';
  [[-2,-3],[5,-2],[2,4]].forEach(([a,b])=>{ctx.beginPath();ctx.arc(a,b,1.7,0,Math.PI*2);ctx.fill();});
  ctx.restore();
}

