  function drawSlice(s){
    const bob=Math.sin(elapsed*4+s.phase)*3, x=s.x,y=s.y+bob;
    ctx.save();ctx.translate(x,y);ctx.rotate(.1*Math.sin(elapsed*2+s.phase));
    ctx.shadowColor='#ffca66';ctx.shadowBlur=16;ctx.fillStyle='#ffd978';
    ctx.beginPath();ctx.moveTo(-11,-9);ctx.lineTo(12,-5);ctx.lineTo(3,12);ctx.closePath();ctx.fill();ctx.shadowBlur=0;
    ctx.strokeStyle='#fff0ad';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#f58a45';
    [[-2,-3],[5,-2],[2,4]].forEach(([a,b])=>{ctx.beginPath();ctx.arc(a,b,1.7,0,Math.PI*2);ctx.fill();});
    ctx.restore();
  }
  function drawPizza(){
    const bob=Math.sin(elapsed*8)*2;
    ctx.save();ctx.translate(pizza.x,pizza.y+bob);ctx.rotate(pizza.angle*.16);
    ctx.shadowColor='#ff553d';ctx.shadowBlur=24;ctx.fillStyle='#ba583c';ctx.beginPath();ctx.arc(0,0,21,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;
    ctx.fillStyle='#f4bf57';ctx.beginPath();ctx.arc(0,0,17,0,Math.PI*2);ctx.fill();
    ctx.strokeStyle='#ffe18c';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,14.5,0,Math.PI*2);ctx.stroke();
    ctx.fillStyle='#d65242';[[0,-9],[-8,2],[8,3],[-3,9]].forEach(([x,y])=>{ctx.beginPath();ctx.arc(x,y,3,0,Math.PI*2);ctx.fill();});
    // furious eyes and a wobbly villain grin
    ctx.strokeStyle='#49302d';ctx.lineWidth=2.3;ctx.lineCap='round';
    ctx.beginPath();ctx.moveTo(-9,-7);ctx.lineTo(-3,-5);ctx.moveTo(3,-5);ctx.lineTo(9,-7);ctx.stroke();
    ctx.fillStyle='#28222a';ctx.beginPath();ctx.arc(-6,-3,1.8,0,Math.PI*2);ctx.arc(6,-3,1.8,0,Math.PI*2);ctx.fill();
